def analyze_step_run(candles,regime,profile,sequence,tick_size):
    direction="buy" if regime.get("direction")=="bullish" else "sell" if regime.get("direction")=="bearish" else None;extended=sequence.get("extension_state") in {"extended","extreme"};valid=bool(direction and not extended and float(profile.get("directional_efficiency") or 0)>=.35)
    return {"direction":direction,"run_start":None,"run_end":regime.get("formed_at"),"run_length_candles":sequence.get("current_sequence_length",0),"run_length_ticks":None,"pullback_depth_ticks":profile.get("average_pullback_ticks"),"pullback_depth_atr":profile.get("average_pullback_atr"),"structure_valid":bool(direction),"extended":extended,"valid":valid,"rejection_reasons":[] if valid else ["A non-extended confirmed directional run is required."]}
